        {"v_t1a", new Line("Where did you get that? ... Okay. Okay. Sit down. But keep your voice low.",
            new[] { 5, 9, 13, 17, 23, 27, 33, 39, 43, 49, 53, 58, 63, 69, 74 },
            new[] { 0.24f, 0.42f, 0.54f, 0.66f, 0.96f, 1.74f, 2.34f, 2.76f, 3.06f, 3.60f, 3.96f, 4.14f, 4.32f, 4.44f, 5.02f })},
        {"v_t1b", new Line("Kamala-ji... she's a good woman. ... Alright. Sit. But if anyone asks, you're just drinking chai.",
