            new[] { 0.93f, 1.59f, 2.52f, 3.06f, 3.24f, 3.42f, 3.54f, 3.72f, 4.02f, 4.56f, 5.22f, 5.58f, 5.64f, 5.82f, 6.36f, 7.38f, 7.50f, 8.16f, 8.64f, 10.02f, 10.50f, 10.80f, 11.58f, 11.70f, 12.06f, 13.32f, 13.56f, 14.04f, 14.64f, 14.82f, 15.54f, 15.72f, 15.84f, 16.14f, 17.22f, 17.40f, 17.94f, 18.60f, 18.78f, 19.20f, 19.56f, 20.46f, 20.76f, 21.18f, 21.42f, 21.84f, 22.08f, 22.74f })},
        {"v_t2c", new Line("I don't know exactly. But the last time I spoke to her, she mentioned the Kali Temple. She said, Kali Ma will protect the truth. I thought she was being poetic, but now I think she meant it literally.",
