        {"a3_pandit_1", new Line("You are looking for Priya. I can see it in your eyes. You have the same look she had when she came to me. Desperate, and determined.",
            new[] { 3, 7, 15, 19, 26, 28, 32, 36, 39, 42, 47, 53, 57, 62, 66, 71, 76, 80, 84, 89, 93, 98, 101, 105, 116, 120, 132 },
