        {"cur0_04", new Line("A woman disappears, and the city files her under \"left voluntarily.\" The city is a poor librarian.",
            new[] { 1, 7, 19, 23, 27, 32, 38, 42, 48, 54, 68, 72, 77, 80, 82, 87, 98 },
            new[] { 0.30f, 0.48f, 1.38f, 1.80f, 1.98f, 2.10f, 2.64f, 2.88f, 3.42f, 3.90f, 4.80f, 5.70f, 5.88f, 6.12f, 6.30f, 6.48f, 7.62f })},
        {"cur0_05", new Line("But you did not believe the filing. You walked into a life interrupted mid-sentence. A chai gone cold. A suitcase half-packed. A window forced from the outside.",
            new[] { 3, 7, 11, 15, 23, 27, 35, 39, 46, 51, 53, 58, 70, 84, 86, 91, 96, 102, 104, 113, 126, 128, 135, 142, 147, 151, 160 },
