        {"cur0_06", new Line("You noticed. In my experience, noticing is the rarest courage. It is also the cheapest. Consequently, everyone can afford it, and almost no one buys it.",
            new[] { 3, 12, 15, 18, 30, 39, 42, 46, 53, 62, 65, 68, 73, 77, 87, 101, 110, 114, 121, 125, 129, 136, 139, 143, 148, 152 },
