            new[] { 0.30f, 0.54f, 0.90f, 1.14f, 1.32f, 2.22f, 2.40f, 2.58f, 2.94f, 3.90f, 4.08f, 4.56f, 5.52f, 6.30f, 6.66f, 7.41f })},
        {"cur0_11", new Line("Ask yourself: why would a friend warn you away, and then leave you a thread to pull?",
