        {"cur1_05", new Line("Drivers are confessional. They hear the sentences people say to the air. If you had not asked the man who drove her what he heard, you have left a witness idling at the curb.",
            new[] { 7, 11, 25, 30, 35, 39, 49, 56, 60, 63, 67, 72, 75, 79, 83, 87, 93, 97, 101, 105, 111, 115, 120, 123, 130, 134, 139, 144, 146, 154, 161, 164, 168, 174 },
